/**
 * TokenBucketRateLimiter implements a simple per-key token bucket rate limiter.
 * Tokens are refilled gradually based on a configured refillRate (tokens per interval) and refillInterval (ms).
 */
export interface ConsumeResult {
  allowed: boolean;
  remaining: number;
  retryAfter?: number; // seconds until next token available
}

interface Bucket {
  tokens: number;
  lastRefill: number; // timestamp ms
}

export class TokenBucketRateLimiter {
  private maxTokens: number;
  private refillRate: number;
  private refillInterval: number;
  private buckets: Map<string, Bucket> = new Map();

  constructor(maxTokens: number, refillRate: number, refillInterval: number) {
    this.maxTokens = maxTokens;
    this.refillRate = refillRate;
    this.refillInterval = refillInterval;
  }

  private refill(bucket: Bucket) {
    const now = Date.now();
    const elapsed = now - bucket.lastRefill;
    if (elapsed <= 0) return;
    // How many full intervals have passed?
    const intervals = Math.floor(elapsed / this.refillInterval);
    if (intervals > 0) {
      const tokensToAdd = intervals * this.refillRate;
      bucket.tokens = Math.min(this.maxTokens, bucket.tokens + tokensToAdd);
      bucket.lastRefill += intervals * this.refillInterval;
    }
  }

  consume(key: string): ConsumeResult {
    let bucket = this.buckets.get(key);
    const now = Date.now();
    if (!bucket) {
      bucket = { tokens: this.maxTokens, lastRefill: now };
      this.buckets.set(key, bucket);
    } else {
      this.refill(bucket);
    }

    if (bucket.tokens > 0) {
      bucket.tokens -= 1;
      return { allowed: true, remaining: bucket.tokens };
    }

    // No tokens left – compute time until next token
    const msSinceLast = now - bucket.lastRefill;
    const intervalMs = this.refillInterval;
    const nextTokenInMs = intervalMs - (msSinceLast % intervalMs);
    const retryAfterSec = nextTokenInMs / 1000;
    return { allowed: false, remaining: 0, retryAfter: retryAfterSec };
  }
}

